function oswec_regular_derived_60s(coreDir, applicationsDir, hydroFile, outDir)
assert(isfolder(coreDir) && isfolder(applicationsDir) && isfile(hydroFile) ...
    && ~isfolder(outDir), 'Pinned source paths and a fresh output directory required');
mkdir(outDir);
scratch = fullfile(outDir, 'scratch');
mkdir(fullfile(scratch, 'Wave_Markers'));
mkdir(fullfile(scratch, '_Common_Input_Files'));
copyfile(fullfile(applicationsDir, 'Wave_Markers', 'OSWEC'), ...
    fullfile(scratch, 'Wave_Markers', 'OSWEC'));
copyfile(fullfile(applicationsDir, '_Common_Input_Files', 'OSWEC'), ...
    fullfile(scratch, '_Common_Input_Files', 'OSWEC'));
caseDir = fullfile(scratch, 'Wave_Markers', 'OSWEC');
copyfile(fullfile(coreDir, 'examples', 'OSWEC', 'OSWEC.slx'), ...
    fullfile(caseDir, 'OSWEC.slx'));
copyfile(hydroFile, fullfile(scratch, '_Common_Input_Files', ...
    'OSWEC', 'hydroData', 'oswec.h5'));
inputFile = fullfile(caseDir, 'wecSimInputFile.m');
input = fileread(inputFile);
assert(count(input, 'simu.endTime=400;') == 1 ...
    && count(input, 'simu.rampTime = 100;') == 1 ...
    && count(input, 'waves.height = 2.5;') == 2 ...
    && count(input, 'waves.period = 8;') == 2 ...
    && count(input, "simu.explorer='on';") == 1 ...
    && contains(input, "simu.solver = 'ode4';") ...
    && contains(input, 'simu.dt = 0.1;'), ...
    'Pinned OSWEC input changed');
input = strrep(input, 'simu.endTime=400;', 'simu.endTime=60;');
input = strrep(input, 'simu.rampTime = 100;', 'simu.rampTime = 15;');
input = strrep(input, 'waves.height = 2.5;', 'waves.height = 1.3;');
input = strrep(input, 'waves.period = 8;', 'waves.period = 6.5;');
input = strrep(input, "simu.explorer='on';", "simu.explorer='off';");
file = fopen(inputFile, 'w');
assert(file ~= -1, 'Could not edit scratch input');
fprintf(file, '%s', input);
fclose(file);
addpath(genpath(fullfile(coreDir, 'source')));
cd(caseDir);
wecSim;
assert(simu.endTime == 60 && simu.rampTime == 15 ...
    && waves.height == 1.3 && waves.period == 6.5);
b = output.bodies(1);
p = output.ptos(1);
assert(numel(b.time) == 601 && numel(p.time) == 601 ...
    && all(isfinite(b.position), 'all') ...
    && all(isfinite(p.powerInternalMechanics), 'all'), ...
    'Derived source output incomplete');
writematrix([b.time(:), b.position(:,1), b.position(:,3), ...
    b.position(:,5), b.velocity(:,1), b.velocity(:,3), ...
    b.velocity(:,5)], fullfile(outDir, 'flap.csv'));
writematrix([p.time(:), p.position(:,5), p.velocity(:,5), ...
    p.forceInternalMechanics(:,5), p.powerInternalMechanics(:,5)], ...
    fullfile(outDir, 'pto.csv'));
writematrix(waves.waveAmpTime, fullfile(outDir, 'wave.csv'));
fprintf('OSWEC_REGULAR_DERIVED_PASSED samples=%d\n', numel(b.time));
close_system('OSWEC', 0);
end
